package com.bankpli.javabank.transfer;import java.math.BigDecimal;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.Optional;import org.springframework.stereotype.Component;
@Component public class TransferValidator {private static final BigDecimal LARGE=new BigDecimal("10000000.00");public Optional<String> validate(TransferRequest r,LocalDate today,boolean sameOwner){if(r==null)return Optional.of("Transfer request is required");if(r.amount()==null||r.amount().signum()<=0)return Optional.of("Transfer amount must be positive");if(r.priority()==null)return Optional.of("Invalid priority code");if(r.type()==null)return Optional.of("Invalid transfer type");if(r.amount().compareTo(LARGE)>0){if(r.priority()==Priority.STANDARD)return Optional.of("Large transfers require high priority");if(r.type()==TransferType.INTERNAL&&!sameOwner)return Optional.of("Large internal transfers require same customer");if(r.type()==TransferType.EXTERNAL&&!r.externalBankVerified())return Optional.of("External bank verification failed");if(r.type()==TransferType.WIRE&&!r.wireAuthorized())return Optional.of("Wire transfer not authorized");}if(eq(r.fromAccount(),r.toAccount())&&eq(r.fromSortCode(),r.toSortCode()))return Optional.of("Source and target accounts must differ");if(r.scheduledDate()==null)return Optional.of("Scheduled date is required");if(r.scheduledDate().isBefore(today))return Optional.of("Scheduled date cannot be in the past");if(ChronoUnit.DAYS.between(today,r.scheduledDate())>365)return Optional.of("Cannot schedule more than 1 year ahead");return Optional.empty();}private boolean eq(String a,String b){return a!=null&&a.equals(b);}}
